responses.text:
{
  "instrument": "Directive (EU) 2023/2673 — Shopify blog",
  "jurisdiction": "EU",
  "summary": "Add a clearly labelled withdrawal button with a confirmation step and a receipt on a durable medium before 19 June 2026. This Shopify blog post explains the amended Consumer Rights Directive for online stores selling to EU consumers.",
  "effective_dates": [
    "2026-06-19"
  ],
  "obligations": [
    {
      "text": "Add a labelled withdrawal button with a confirmation step and a receipt.",
      "quote": "The amended Consumer Rights Directive requires every online store selling to EU consumers to add a clearly labelled withdrawal button, followed by a confirmation step and a receipt on a durable medium."
    }
  ]
}
